window.kbPageData["views/entry/k-3d064a3e81bf28f4"] = {"key":"entry/k-3d064a3e81bf28f4","state":{"route":"entry/k-3d064a3e81bf28f4"},"node":{"id":"k-3d064a3e81bf28f4","mode":"k","title":"剩余价值理论 · 资本","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["概念与词义"],"出处性质":["理论手册"],"学科":["经济"],"来源主题":["马克思主义政治经济学"],"资料类别":["非时政"]},"seeAlso":["k-2e159cf92a6c2d61","k-95ed7451f26bb7d8"],"directorySummary":"二、资本\n资本在资本主义生产过程中以生产资料和劳动力两种形态存在。根据这两部分资本在剩\n余价值生产中所起的不同作用，可将资本分为不变资本和可变资本。\n不变资本，是指以生产资料形态存在的那部分资本，其价值在生产过程中一次或多次转\n移到新产品中去，不会发生增殖。\n可变资本，是指以劳动力价值形态存在的那部…","sources":[{"id":"33f9e33191c8bd04","label":"剩余价值理论 · 资本","topic":"马克思主义政治经济学","category":"非时政","text":"二、资本\n资本在资本主义生产过程中以生产资料和劳动力两种形态存在。根据这两部分资本在剩\n余价值生产中所起的不同作用，可将资本分为不变资本和可变资本。\n不变资本，是指以生产资料形态存在的那部分资本，其价值在生产过程中一次或多次转\n移到新产品中去，不会发生增殖。\n可变资本，是指以劳动力价值形态存在的那部分资本，在生产过程中可以使价值增殖。\n可变资本只有劳动力。\n（粉笔敲黑板：明确不变资本和可变资本以什么形态存在，会不会产生增殖）","source":{"doc":"3ccc56f4000d1642c2d1","first":10,"last":10,"page":10,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{"k-2e159cf92a6c2d61":{"id":"k-2e159cf92a6c2d61","mode":"k","type":"概念与词义","title":"可变资本","qs":[],"count":0},"k-95ed7451f26bb7d8":{"id":"k-95ed7451f26bb7d8","mode":"k","type":"概念与词义","title":"不变资本","qs":[],"count":0}},"references":{},"topics":[],"units":{"k-3d064a3e81bf28f4":[]}};
